/**
 * The Spy in the Guildhall — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { GUILDHALL_SPY_TEMPLATE } from '../guildhall-spy';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Spy in the Guildhall — template structure", () => {
  it('carries its identity', () => {
    expect(GUILDHALL_SPY_TEMPLATE.id).toBe('encounter.town.guildhall_spy');
    expect(GUILDHALL_SPY_TEMPLATE.reach).toBe('shadow');
    expect(GUILDHALL_SPY_TEMPLATE.rarityTier).toBe(2);
    expect(GUILDHALL_SPY_TEMPLATE.steps).toHaveLength(1);
  });

  it('step 0 deals the authored hand', () => {
    const step = GUILDHALL_SPY_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['spy.send_a_guilty_dream', 'spy.show_an_honest_face']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['mind']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(GUILDHALL_SPY_TEMPLATE.settings).toEqual(['urban']);
    expect(GUILDHALL_SPY_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(GUILDHALL_SPY_TEMPLATE.consequenceDraw).toEqual(['story_seed', 'membership']);
    expect(GUILDHALL_SPY_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.guildhall_spy',
          reach: 'shadow',
          rarityTier: 2,
        }),
        GUILDHALL_SPY_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
